# Encontros 51 a 60: argumentação (tese, tipos de argumento, repertório, gêneros argumentativos, resumo, resenha, tema e recorte).
from base import M, A, VF, C, T, E

E(51, 'Argumentação', 'Tese, argumento e ponto de vista',
  aquecimento='Pergunte à turma: “O uniforme escolar deveria ser obrigatório?”. Peça a três alunos uma opinião com um “porque” e anote no quadro: a opinião é a tese; o “porque” é o argumento.',
  quadro=['# Tema x tese',
    '- Tema: o assunto sobre o qual se escreve. Ex.: o uso do celular pelos jovens.',
    '- Tese: a opinião central que o autor defende sobre o tema. Ex.: O uso excessivo do celular prejudica o sono e os estudos dos jovens.',
    '- O tema não é verdadeiro nem falso; a tese é uma posição, que pode ser aceita ou contestada.',
    '- Ponto de vista: o modo como o autor enxerga o tema. A tese é esse ponto de vista escrito em uma frase clara.',
    '# Frases-modelo de tese',
    '- É fundamental (urgente, necessário) + ação + pois + motivo. Ex.: É urgente ampliar as ciclovias, pois elas tornam o trânsito mais seguro.',
    '- X é causado por A e B. Ex.: A evasão escolar é causada pela necessidade de trabalhar e pela falta de apoio ao estudante.',
    '- Embora X, Y. Ex.: Embora a internet aproxime as pessoas, ela também pode favorecer o isolamento.',
    '- Na redação do ENEM, a tese aparece na introdução e, de preferência, já anuncia os argumentos.',
    '# Argumento: a razão que sustenta a tese',
    '- O argumento responde à pergunta “Por quê?” feita à tese.',
    '- Tese: A leitura deve ser incentivada desde a infância. Por quê? Argumento: porque amplia o vocabulário e a compreensão.',
    '- Argumento forte: verdadeiro, ligado à tese, explicado e comprovado (exemplo, dado, autoridade, causa e consequência).',
    '- Argumento fraco: achismo (“acho e pronto”), generalização (“todo jovem é preguiçoso”), senso comum (“sempre foi assim”).',
    '# Falácias: raciocínios que parecem bons, mas enganam',
    '- Generalização apressada: concluir algo sobre todos a partir de poucos casos. Ex.: Meu primo largou a escola e ficou rico; logo, estudar não serve para nada.',
    '- Ataque à pessoa: criticar quem fala, e não o que é dito. Ex.: Não aceite a ideia do Pedro para o grêmio, porque ele tira notas baixas.',
    '- Apelo à maioria: achar que algo é certo só porque muita gente acredita ou faz. Ex.: Todo mundo compartilhou essa notícia; então, ela é verdadeira.',
    '# Fique atento',
    '- Tese não é tema nem pergunta: “O lixo nas cidades” é tema; “O que fazer com o lixo?” é pergunta; “A coleta seletiva precisa ser ampliada” é tese.',
    '- Na redação do ENEM, evite “eu acho”: prefira a 3ª pessoa (“É preciso…”, “Nota-se que…”).',
    '- Argumento sem explicação vira opinião solta: afirme, explique e comprove.',
    '- Tese “em cima do muro” (“tem lados bons e ruins”) enfraquece o texto: posicione-se.'],
  q=[M('Qual frase apresenta uma TESE, e não apenas um tema?', ['A violência nas escolas brasileiras e o papel da família.', 'O combate à violência escolar exige diálogo com as famílias.', 'A escola, a família e a violência no Brasil de hoje.', 'Como diminuir a violência nas escolas do Brasil?'], 1),
     M('Em “A leitura deve ser incentivada desde a infância, porque amplia o vocabulário”, o trecho “porque amplia o vocabulário” é:', ['o tema', 'a tese', 'o argumento', 'a conclusão'], 2),
     M('Qual pergunta, feita à tese, ajuda a encontrar o argumento?', ['Por quê?', 'Quando?', 'Onde?', 'Quem?'], 0),
     T('As bibliotecas públicas deveriam abrir também aos sábados e domingos. Em primeiro lugar, é nos fins de semana que muitos trabalhadores e estudantes têm tempo livre para ler e pesquisar; fechar as portas justamente nesses dias afasta quem mais precisa delas. Além disso, a biblioteca é um espaço gratuito de cultura e convivência, uma alternativa segura de lazer para famílias que não podem pagar por outras atividades. Há quem diga que ninguém mais lê livros e que, por isso, abrir nos fins de semana seria desperdício. Essa afirmação, porém, é uma generalização: basta visitar uma biblioteca para ver estudantes disputando mesas e computadores. Portanto, ampliar o horário das bibliotecas é investir em educação e cidadania.',
       fonte='Texto elaborado para esta atividade.', titulo='Biblioteca aberta no fim de semana', para=4),
     M('Qual é a tese defendida no texto?', ['As bibliotecas públicas deveriam abrir também aos sábados e domingos.', 'Ninguém mais lê livros; por isso, abrir as bibliotecas seria desperdício.', 'Muitas famílias não podem pagar por outras atividades de lazer.', 'Os estudantes disputam mesas e computadores nas bibliotecas.'], 0),
     A('Copie do texto um argumento que sustenta a tese.', '“é nos fins de semana que muitos trabalhadores e estudantes têm tempo livre para ler e pesquisar” ou “a biblioteca é um espaço gratuito de cultura e convivência, uma alternativa segura de lazer…”.', 2),
     M('No texto, a afirmação “ninguém mais lê livros” aparece como:', ['uma generalização, que o autor contesta', 'o principal argumento a favor da tese', 'um dado de pesquisa com fonte confiável', 'a conclusão a que o autor chega'], 0),
     M('No texto, a palavra “Portanto” introduz:', ['a conclusão, que retoma a tese', 'um argumento contrário à tese', 'um exemplo de frequentador', 'a causa de um problema'], 0),
     M('O raciocínio “Meu tio fumou a vida inteira e viveu 90 anos; logo, cigarro não faz mal” é um exemplo de:', ['generalização apressada', 'ataque à pessoa', 'apelo à maioria', 'argumento por dados'], 0),
     M('Em qual frase há um ataque à pessoa, e não à ideia?', ['A proposta do grêmio é ruim, porque o presidente do grêmio é antipático.', 'A proposta do grêmio é ruim, porque custaria mais do que a escola pode pagar.', 'A proposta do grêmio é boa, porque atende a um pedido antigo dos alunos.', 'A proposta do grêmio precisa de ajustes no horário das atividades.'], 0),
     M('Qual tese está “em cima do muro”, sem posição clara?', ['As redes sociais têm lados bons e lados ruins.', 'As redes sociais precisam de regras claras para proteger crianças.', 'O uso excessivo das redes sociais prejudica o sono dos adolescentes.', 'A educação digital deve fazer parte do currículo escolar.'], 0),
     VF('Sobre tema, tese e argumento, marque V ou F:', [
       ('O tema é o assunto; a tese é a opinião defendida sobre esse assunto.', True),
       ('Uma pergunta, como “O que fazer com o lixo?”, já é uma tese.', False),
       ('Um argumento forte é verdadeiro, ligado à tese e bem explicado.', True),
       ('Palavras como “todos” e “ninguém” deixam qualquer argumento mais forte.', False),
       ('Na redação do ENEM, recomenda-se apresentar a tese já na introdução.', True)]),
     C('Associe cada frase ao problema de argumentação que ela apresenta:', [
       ('“Eu acho que é assim e pronto.”', 'achismo'),
       ('“Todo adolescente é irresponsável.”', 'generalização'),
       ('“Sempre foi assim; então, está certo.”', 'senso comum'),
       ('“Milhões de pessoas tomam esse chá; logo, ele cura tudo.”', 'apelo à maioria'),
       ('“Não ouça a opinião da Ana: ela é nova na escola.”', 'ataque à pessoa')]),
     A('Transforme o tema em uma tese: “O desperdício de alimentos no Brasil”.', 'Resposta pessoal. Ex.: O desperdício de alimentos no Brasil precisa ser combatido com educação para o consumo e incentivo à doação, pois é inaceitável jogar comida fora em um país onde ainda há fome.', 2),
     A('Escreva dois argumentos para a tese: “A prática de esportes deve ser incentivada nas escolas”.', 'Resposta pessoal. Ex.: 1) o esporte melhora a saúde física e mental; 2) ensina a trabalhar em equipe e a respeitar regras e adversários.', 2),
     A('Explique por que “Sempre foi assim” não é um bom argumento.', 'Porque é senso comum: o fato de algo acontecer há muito tempo não prova que seja certo ou verdadeiro; falta explicação e comprovação.', 2),
     A('Reescreva o argumento fraco, tornando-o mais forte e sem generalizar: “Todo jovem só pensa em celular, então ninguém lê mais.”', 'Resposta pessoal. Ex.: Muitos jovens passam várias horas por dia no celular, o que pode reduzir o tempo dedicado à leitura; por isso, escola e família devem incentivar o hábito de ler.', 3),
  ],
  producao='Escolha um tema: uniforme escolar obrigatório, aulas de educação financeira na escola ou tempo de tela para crianças. Escreva um parágrafo argumentativo de 6 a 8 linhas com uma tese clara, dois argumentos explicados e uma frase de conclusão. Sublinhe a tese e numere os argumentos (1 e 2).')

E(52, 'Argumentação', 'Tipos de argumento I: exemplificação, dados e autoridade',
  aquecimento='Pergunte: “Para convencer alguém a fazer um curso, o que vocês usariam: o exemplo de uma pessoa que fez, um número ou a opinião de um especialista?”. Classifique as respostas no quadro em três colunas.',
  quadro=['# Tipos de argumento: formas de provar a tese',
    '- Argumentar é sustentar a tese com provas. Cada tipo de argumento é uma forma diferente de comprovar o que se afirma.',
    '- Neste encontro: exemplificação, dados (comprovação) e autoridade (citação).',
    '# Argumento por exemplificação',
    '- Usa um caso concreto (fato, situação, pessoa, lugar) para ilustrar e confirmar a tese.',
    '- Ex.: A tecnologia pode promover inclusão: leitores de tela permitem que pessoas cegas usem o celular com autonomia.',
    '- O exemplo deve ser real ou possível, específico e ligado à tese. Um caso isolado ilustra, mas não prova uma regra geral.',
    '# Argumento por dados (comprovação)',
    '- Usa números, pesquisas e fatos verificáveis para mostrar que a tese tem base na realidade.',
    '- Indique sempre a fonte: IBGE, OMS, ONU, universidades, órgãos públicos. Ex.: Dados do IBGE mostram que a população brasileira está envelhecendo.',
    '- Nunca invente números. Se não lembrar o dado exato, use uma formulação geral e verdadeira: “pesquisas indicam aumento de…”.',
    '- Em exercícios, dados fictícios devem ser avisados. Ex.: Na pesquisa fictícia da turma, 18 de 30 alunos dormem menos de 7 horas.',
    '# Argumento de autoridade (citação)',
    '- Apoia a tese na palavra de alguém reconhecido no assunto: especialista, pensador, instituição, obra ou lei.',
    '- Ex.: Paulo Freire, em “Pedagogia do Oprimido”, defende uma educação que forme sujeitos críticos.',
    '- Ex.: A Constituição de 1988, no artigo 205, define a educação como direito de todos e dever do Estado e da família.',
    '- Citação direta: frase exata, entre aspas, com o autor. Paráfrase: a ideia do autor com suas palavras (“Para Kant, …”).',
    '- A autoridade deve ser da área: a opinião de um ator famoso não comprova um fato médico.',
    '# Expressões para introduzir cada tipo',
    '- Exemplo: “Um exemplo disso é…”, “Prova disso é…”, “É o caso de…”.',
    '- Dados e autoridade: “De acordo com…”, “Segundo…”, “Conforme…”, “Dados do… revelam que…”.',
    '# Fique atento',
    '- Dado sem fonte perde força; dado inventado é desonestidade e enfraquece o texto.',
    '- Não atribua a alguém uma frase que ele não disse: na dúvida, use paráfrase.',
    '- Citação não substitui explicação: depois de citar, mostre como ela se liga à tese.',
    '- Afirme, comprove e explique: o tipo de argumento é a prova, não o parágrafo inteiro.'],
  q=[M('Qual frase usa argumento por EXEMPLIFICAÇÃO?', ['Ler amplia o vocabulário: foi o que aconteceu com Ana, que passou a escrever melhor no clube de leitura.', 'Segundo a Constituição de 1988, a educação é direito de todos e dever do Estado e da família.', 'Na pesquisa fictícia da turma, 20 de 30 alunos disseram que gostariam de ler mais do que leem hoje.', 'Ler é importante simplesmente porque eu acho que é, e ninguém vai me convencer do contrário.'], 0),
     M('O argumento “Segundo a Organização Mundial da Saúde, saúde é o completo bem-estar físico, mental e social” é do tipo:', ['autoridade', 'exemplificação', 'dados estatísticos', 'senso comum'], 0),
     M('Qual destas é uma fonte confiável para dados sobre a população brasileira?', ['o IBGE (Instituto Brasileiro de Geografia e Estatística)', 'um comentário anônimo publicado em uma rede social', 'uma corrente de mensagens recebida pelo celular', 'a opinião de um vizinho que mora no bairro há anos'], 0),
     T('O grêmio do Colégio Horizonte defende que a escola abra uma sala de leitura durante o recreio. Uma pesquisa feita pelo grêmio com 300 alunos mostrou que 210 deles gostariam de ler mais, mas não encontram um lugar tranquilo para isso. Além disso, uma escola vizinha serve de exemplo: depois que montou um cantinho de leitura com pufes e gibis, os empréstimos da biblioteca aumentaram. O grêmio lembra ainda que a Constituição Federal, no artigo 205, define a educação como direito de todos e preparo para o exercício da cidadania. Para os estudantes, oferecer um espaço de leitura é uma forma simples e barata de cumprir esse dever.',
       fonte='Texto elaborado para esta atividade (escola e dados fictícios).', titulo='Leitura no recreio', para=4),
     M('No texto, o trecho “210 deles gostariam de ler mais” é um argumento de:', ['dados (comprovação)', 'autoridade', 'exemplificação', 'senso comum'], 0),
     M('Segundo a pesquisa citada no texto, gostariam de ler mais:', ['7 em cada 10 alunos', '2 em cada 10 alunos', '3 em cada 10 alunos', '9 em cada 10 alunos'], 0),
     M('No texto, a experiência da escola vizinha, com o cantinho de leitura, é usada como argumento de:', ['exemplificação', 'dados estatísticos', 'autoridade', 'alusão histórica'], 0),
     A('Que argumento de autoridade aparece no texto? Qual é a fonte citada?', 'A ideia de que a educação é direito de todos e preparo para o exercício da cidadania; a fonte é a Constituição Federal, artigo 205.', 2),
     M('Para defender a importância da vacinação, qual autoridade é a mais adequada?', ['a Organização Mundial da Saúde (OMS)', 'um cantor famoso nas redes sociais', 'um influenciador digital de moda', 'um campeão brasileiro de xadrez'], 0),
     M('Qual frase usa dados de forma INADEQUADA?', ['Todo mundo sabe que 99% dos jovens odeiam ler.', 'Dados do IBGE mostram que a população brasileira está envelhecendo.', 'Segundo a OMS, a depressão atinge pessoas no mundo todo.', 'Na pesquisa fictícia da turma, 12 de 30 alunos vêm de ônibus.'], 0),
     M('Em “Para o educador Paulo Freire, a educação deve formar sujeitos críticos”, a autoridade é citada em forma de:', ['paráfrase, com as palavras de quem escreve', 'citação direta, com as palavras exatas entre aspas', 'dado estatístico, com número e fonte', 'exemplo pessoal, vivido por quem escreve'], 0),
     VF('Sobre exemplificação, dados e autoridade, marque V ou F:', [
       ('Um caso concreto ilustra a tese, mas um caso isolado não prova uma regra geral.', True),
       ('Dados sem fonte têm a mesma força que dados com fonte confiável.', False),
       ('Leis, como o ECA e a Constituição, podem ser usadas como argumento de autoridade.', True),
       ('Se esquecer o número exato, o estudante pode inventar um valor parecido.', False),
       ('Depois de uma citação, é preciso explicar como ela se relaciona com a tese.', True)]),
     C('Associe cada trecho ao tipo de argumento:', [
       ('“É o caso de Dona Maria, que voltou a estudar na EJA aos 50 anos e hoje ajuda os netos nas tarefas.”', 'exemplificação'),
       ('“Segundo o artigo 196 da Constituição, a saúde é direito de todos e dever do Estado.”', 'autoridade (lei)'),
       ('“Na pesquisa fictícia da turma, 25 de 32 alunos usam o celular antes de dormir.”', 'dados (comprovação)'),
       ('“Para o sociólogo Zygmunt Bauman, vivemos uma modernidade líquida, de relações frágeis.”', 'autoridade (pensador)')]),
     A('Complete com a expressão adequada: “____ o Estatuto da Criança e do Adolescente, crianças e adolescentes têm direito à proteção integral.”', 'De acordo com (também valem: Segundo / Conforme).', banco=['De acordo com', 'Um exemplo disso é', 'Prova disso é']),
     A('Escreva um argumento por exemplificação para a tese: “O trabalho voluntário fortalece a comunidade”.', 'Resposta pessoal. Ex.: Um exemplo disso são os mutirões de vizinhos que limpam praças e reformam espaços de lazer, criando laços entre os moradores.', 2),
     A('Dados fictícios: “Em uma turma de 30 alunos, 12 disseram que viriam de bicicleta se a escola tivesse um lugar seguro para guardá-la.” Use esses dados em uma frase que defenda a tese “A escola precisa de um bicicletário”.', 'Resposta pessoal. Ex.: Na pesquisa da turma, 12 de 30 alunos afirmaram que viriam de bicicleta se houvesse um local seguro para guardá-la; portanto, a escola precisa de um bicicletário.', 2),
     A('Explique o que está errado no argumento: “Como disse um famoso especialista, 80% dos brasileiros nunca leram um livro.”', 'O especialista não é identificado (autoridade vaga) e o número não tem fonte verificável, podendo ser inventado; falta dizer quem afirmou e onde a informação foi publicada.', 2),
  ],
  producao='Escreva um parágrafo argumentativo de 7 a 10 linhas defendendo a tese “A prática de atividade física deve ser incentivada desde a infância”. Use um exemplo concreto e um argumento de autoridade (por exemplo, a definição de saúde da OMS ou o artigo 196 da Constituição). Não invente números. Indique entre parênteses o tipo de cada argumento.')

E(53, 'Argumentação', 'Tipos de argumento II: causa e consequência, comparação, alusão histórica e contra-argumentação',
  aquecimento='Jogo do “E daí?”: diga um fato (“Muita gente joga lixo na rua.”) e peça à turma que responda em cadeia com consequências (bueiros entopem → ruas alagam → doenças se espalham).',
  quadro=['# Argumento por causa e consequência',
    '- Explica por que um problema acontece (causa) e o que ele provoca (consequência).',
    '- Ex.: Como muitas cidades não têm coleta seletiva (causa), materiais recicláveis acabam nos aterros (consequência).',
    '- Causa: porque, visto que, já que, uma vez que. Consequência/conclusão: por isso, portanto, consequentemente, de modo que.',
    '# Argumento por comparação',
    '- Aproxima ou contrapõe duas realidades para mostrar semelhanças ou diferenças.',
    '- Ex.: Assim como o corpo precisa de alimento, a mente precisa de leitura e cultura.',
    '- Ex.: Diferentemente de países que investem em trens, o Brasil transporta grande parte de suas cargas por rodovias.',
    '- Conectivos: assim como, da mesma forma que, tal qual, diferentemente de, enquanto, ao passo que.',
    '# Argumento por alusão histórica',
    '- Retoma um fato do passado para explicar ou iluminar um problema do presente.',
    '- Ex.: A Lei Áurea (1888) aboliu a escravidão sem garantir terra, emprego e educação aos libertos, o que ajuda a explicar a desigualdade racial atual.',
    '- Ex.: A censura da ditadura militar (1964–1985) lembra por que a liberdade de imprensa precisa ser defendida.',
    '# Contra-argumentação: concessão + refutação',
    '- Concessão: o autor reconhece uma ideia contrária. Refutação: mostra por que ela não derruba a tese.',
    '- Modelo: “Embora alguns defendam que X, Y, pois Z.”',
    '- Ex.: Embora alguns defendam que videogames só isolam os jovens, muitos jogos estimulam o raciocínio e a cooperação.',
    '- Ex.: É verdade que a coleta seletiva exige investimento; no entanto, ela gera renda e reduz o lixo nos aterros.',
    '- Concessão: embora, ainda que, mesmo que, apesar de. Refutação: mas, porém, contudo, no entanto, todavia.',
    '# Fique atento',
    '- Não troque causa por consequência: em “Os rios transbordaram porque choveu muito”, a chuva é a causa.',
    '- Comparação só funciona entre realidades que têm pontos realmente parecidos.',
    '- Na alusão histórica, confira datas e fatos e relacione o passado ao problema atual.',
    '- Na concessão com “embora”, a sua tese fica na oração principal; nunca termine o parágrafo dando razão ao outro lado.',
    '- “Embora” pede subjuntivo: “Embora alguns defendam” (e não “defendem”).'],
  q=[M('Em “Como choveu muito, as ruas alagaram”, a causa é:', ['“choveu muito”', '“as ruas alagaram”', '“Como”', '“as ruas”'], 0),
     M('Qual conectivo introduz uma comparação?', ['assim como', 'embora', 'portanto', 'porque'], 0),
     M('Qual frase faz uma alusão histórica?', ['Desde 1932 as mulheres votam no Brasil, mas ainda são minoria nos cargos políticos.', 'Muitas mulheres deixam de se candidatar porque acumulam trabalho e cuidado da casa.', 'Assim como uma orquestra precisa de cada instrumento, a democracia precisa da voz de cada cidadão.', 'Se houver mais mulheres na política, as leis tenderão a refletir melhor a sociedade.'], 0),
     T('Embora alguns defendam que vacinar é uma decisão apenas individual, a vacinação é, na verdade, um compromisso coletivo. Quando muitas pessoas deixam de se vacinar, doenças que estavam controladas podem voltar a circular e atingir justamente quem não pode receber certas vacinas, como bebês muito pequenos e pessoas com a imunidade baixa. A história brasileira ajuda a entender esse desafio: em 1904, a Revolta da Vacina, no Rio de Janeiro, mostrou que campanhas feitas sem informação e com autoritarismo geram desconfiança. Assim como naquela época, hoje boatos espalhados pelas redes afastam muitas famílias dos postos de saúde. Por isso, mais do que obrigar, é preciso informar com clareza e respeito.',
       fonte='Texto elaborado para esta atividade.', titulo='Vacina: informação contra o medo', para=4),
     M('No primeiro período do texto, o autor usa:', ['concessão seguida de refutação', 'dados estatísticos com fonte', 'citação direta de um especialista', 'um exemplo da própria vida'], 0),
     M('No texto, o trecho sobre a Revolta da Vacina é um argumento de:', ['alusão histórica', 'exemplificação pessoal', 'dados estatísticos', 'autoridade'], 0),
     A('Copie do texto um trecho com relação de causa e consequência e indique cada parte.', 'Ex.: “Quando muitas pessoas deixam de se vacinar” (causa), “doenças que estavam controladas podem voltar a circular” (consequência). Também vale: boatos espalhados pelas redes (causa) afastam famílias dos postos de saúde (consequência).', 2),
     M('No texto, a expressão “Assim como naquela época” estabelece:', ['uma comparação entre o passado e o presente', 'uma oposição entre duas ideias do texto', 'uma condição para que a vacina funcione', 'uma finalidade para as campanhas de saúde'], 0),
     M('Complete: “____ a internet facilite o acesso à informação, ela também espalha notícias falsas.”', ['Embora', 'Portanto', 'Porque', 'Assim como'], 0),
     M('Qual frase faz concessão e refutação para DEFENDER a tese “A escola deve ensinar educação financeira”?', ['Embora alguns achem que o assunto é tarefa da família, a escola pode garantir que todos aprendam a poupar.', 'Embora a escola possa ensinar a planejar gastos, o assunto deve ficar apenas a cargo da família.', 'A escola deve ensinar educação financeira, porque esse assunto é muito importante para todos.', 'Alguns acham que o assunto é tarefa da família, e eles têm toda a razão nesse ponto do debate.'], 0),
     M('Qual frase usa corretamente um conectivo de consequência?', ['O desmatamento avançou; consequentemente, muitas espécies perderam seu habitat.', 'O desmatamento avançou, embora muitas espécies tenham perdido seu habitat.', 'O desmatamento avançou, assim como muitas espécies perderam seu habitat.', 'O desmatamento avançou, caso muitas espécies percam seu habitat.'], 0),
     VF('Sobre a contra-argumentação, marque V ou F:', [
       ('Na concessão, o autor reconhece uma ideia contrária à sua tese.', True),
       ('Em “Embora alguns defendam X, Y”, a opinião do autor está em Y.', True),
       ('Depois de “embora”, o verbo fica no indicativo: “Embora alguns defendem”.', False),
       ('Quem contra-argumenta deve terminar o parágrafo dando razão ao lado contrário.', False),
       ('A contra-argumentação mostra que o autor conhece o outro lado do debate.', True)]),
     C('Associe cada frase ao tipo de argumento:', [
       ('“A falta de saneamento provoca doenças, o que lota os postos de saúde.”', 'causa e consequência'),
       ('“Assim como um time precisa de treino, a escrita precisa de prática.”', 'comparação'),
       ('“A CLT, de 1943, garantiu direitos que hoje não alcançam os trabalhadores informais.”', 'alusão histórica'),
       ('“Embora alguns digam que o bullying é brincadeira, ele causa sofrimento real às vítimas.”', 'contra-argumentação')]),
     A('Complete a concessão com uma refutação: “Embora alguns defendam que andar de bicicleta na cidade é perigoso, ____.”', 'Resposta pessoal. Ex.: ciclovias bem planejadas tornam o trajeto seguro e ainda reduzem o trânsito e a poluição.', 2),
     A('Cite duas consequências do problema: “Muitos jovens dormem pouco porque ficam no celular até tarde.”', 'Ex.: cansaço e falta de atenção nas aulas; queda no rendimento escolar; irritação e problemas de saúde.', 2),
     A('Una as frases com um conectivo de comparação: “O corpo precisa de exercícios. O cérebro precisa de desafios.”', 'Assim como o corpo precisa de exercícios, o cérebro precisa de desafios. (Também vale: Da mesma forma que…)', banco=['assim como', 'da mesma forma que', 'embora']),
     A('Junte as duas frases em um só período, começando com “Apesar de”: “Algumas pessoas acham cara a reforma das praças. As praças reformadas trazem lazer e segurança ao bairro.”', 'Apesar de algumas pessoas acharem cara a reforma das praças, as praças reformadas trazem lazer e segurança ao bairro.', 2),
  ],
  producao='Escreva um parágrafo de 7 a 10 linhas sobre o tema “O lixo nas cidades brasileiras”. Comece com uma concessão (“Embora alguns pensem que…”), refute-a e use pelo menos um argumento de causa e consequência. Sublinhe a concessão e circule os conectivos.')

E(54, 'Argumentação', 'Repertório sociocultural: legítimo, pertinente e produtivo',
  aquecimento='Pergunte: “Que filme, livro, série, lei ou fato histórico vocês usariam para falar sobre preconceito?”. Anote as respostas e, no fim da aula, avalie com a turma quais são legítimas, pertinentes e produtivas.',
  quadro=['# O que é repertório sociocultural',
    '- Conhecimentos de outras áreas (história, filosofia, sociologia, leis, ciência, literatura, cinema, artes) usados para fundamentar os argumentos.',
    '- Na redação do ENEM, ele é avaliado na Competência 2, que pede aplicar conceitos de várias áreas do conhecimento.',
    '- Ex.: citar o artigo 6º da Constituição, que garante direitos sociais como educação, saúde, moradia e lazer.',
    '# Os três critérios',
    '- Legítimo: verdadeiro e verificável. Nada de autor, lei, frase ou dado inventado.',
    '- Pertinente: ligado ao tema e ao recorte da proposta. Um bom repertório para “saúde mental” pode não servir para “mobilidade urbana”.',
    '- Produtivo: usado para sustentar o argumento, e não como enfeite. Precisa ser explicado e relacionado ao tema.',
    '# Repertório de bolso x específico',
    '- De bolso: serve para muitos temas. Ex.: Constituição (artigos 5º e 6º), Declaração Universal dos Direitos Humanos, Paulo Freire, Bauman.',
    '- Específico: ligado diretamente a um tema. Ex.: Lei Maria da Penha (violência contra a mulher); LGPD (dados na internet).',
    '- O de bolso dá segurança; o específico mostra domínio do assunto. O ideal é combinar os dois.',
    '# Como inserir o repertório em 3 passos',
    '- 1. Apresentar: quem, o quê, quando. Ex.: O sociólogo Zygmunt Bauman chama nossa época de “modernidade líquida”…',
    '- 2. Explicar: dizer com suas palavras o que a referência significa. Ex.: …ou seja, um tempo de relações frágeis e passageiras…',
    '- 3. Relacionar: ligar a referência ao tema e à tese. Ex.: …o que se vê na superficialidade de muitas amizades nas redes sociais.',
    '# Exemplo completo (tema: acesso ao cinema no Brasil)',
    '- O artigo 6º da Constituição inclui o lazer entre os direitos sociais (apresentar). Assim, ir ao cinema não é luxo, mas parte de um direito (explicar).',
    '- Contudo, como muitas cidades não têm nenhuma sala de cinema, grande parte dos brasileiros fica sem esse acesso (relacionar).',
    '# Fique atento',
    '- Repertório de enfeite: citar um pensador sem explicar nem relacionar ao tema não fortalece o argumento.',
    '- Não invente citações nem datas; na dúvida, use paráfrase e omita a data.',
    '- Repetir as informações dos textos motivadores não é repertório próprio: traga conhecimentos seus.',
    '- Repertório ligado só ao assunto geral, fora do recorte do tema, enfraquece o texto.',
    '- Citação famosa não salva argumento fraco: o repertório apoia a sua ideia, não a substitui.'],
  q=[M('O que é repertório sociocultural na redação?', ['Conhecimentos de outras áreas usados para fundamentar os argumentos.', 'Uma lista de palavras difíceis decoradas para enfeitar o texto.', 'A cópia de trechos dos textos motivadores da prova.', 'A opinião pessoal do autor, sem nenhuma referência externa.'], 0),
     M('Para o tema “violência contra a mulher”, qual repertório é específico e pertinente?', ['a Lei Maria da Penha (Lei 11.340/2006)', 'a Lei Geral de Proteção de Dados (Lei 13.709/2018)', 'o Código de Trânsito Brasileiro', 'a Política Nacional de Resíduos Sólidos (Lei 12.305/2010)'], 0),
     T('Tema: “O estigma associado às doenças mentais na sociedade brasileira”.\nParágrafo 1: Na Grécia Antiga, Aristóteles afirmava que o ser humano é um animal político. Além disso, o filme “Coringa” fez muito sucesso nos cinemas. Dessa forma, o estigma das doenças mentais é um problema grave no Brasil.\nParágrafo 2: Segundo a Organização Mundial da Saúde, saúde é um estado de completo bem-estar físico, mental e social, e não apenas a ausência de doença. Essa definição mostra que a saúde mental é tão importante quanto a física. No Brasil, porém, quem enfrenta depressão ou ansiedade ainda é visto, muitas vezes, como fraco ou exagerado, o que leva muitas pessoas a esconder o sofrimento e a adiar a busca por tratamento.',
       fonte='Texto elaborado para esta atividade.', titulo='Dois parágrafos, dois usos do repertório', para=4),
     M('No parágrafo 1, a menção a Aristóteles é:', ['legítima, mas usada como enfeite: não é explicada nem ligada ao estigma', 'legítima, pertinente e produtiva, pois explica bem a origem do estigma', 'ilegítima, pois Aristóteles é um autor inventado pelo estudante', 'produtiva, pois Aristóteles escreveu sobre o tratamento da depressão'], 0),
     M('No parágrafo 1, o filme “Coringa” é mal aproveitado porque:', ['é citado sem explicação nem relação com o argumento', 'é um filme inventado pelo autor do parágrafo', 'não tem nenhuma relação possível com a saúde mental', 'é citado com o nome do diretor e o ano errados'], 0),
     A('No parágrafo 2, identifique as três etapas do uso do repertório: apresentar, explicar e relacionar.', 'Apresentar: “Segundo a Organização Mundial da Saúde, saúde é um estado de completo bem-estar…”; explicar: “Essa definição mostra que a saúde mental é tão importante quanto a física.”; relacionar: “No Brasil, porém, quem enfrenta depressão ou ansiedade ainda é visto… como fraco ou exagerado, o que leva muitas pessoas a esconder o sofrimento…”.', 3),
     M('Comparando os dois parágrafos, é correto afirmar que:', ['o parágrafo 2 usa o repertório de forma produtiva, e o parágrafo 1, como enfeite', 'os dois parágrafos usam o repertório de forma igualmente produtiva', 'o parágrafo 1 é melhor, pois cita um número maior de referências', 'os dois parágrafos apresentam repertórios inventados e ilegítimos'], 0),
     M('Qual uso de repertório é PRODUTIVO?', ['Ailton Krenak critica a separação entre ser humano e natureza; essa visão ajuda a entender por que o desmatamento ainda é tratado como progresso.', 'Como diz Ailton Krenak, a natureza é importante. Enfim, o desmatamento é muito ruim para todos os seres vivos do planeta.', 'Ailton Krenak é um escritor e líder indígena muito conhecido no Brasil e em outros países, com vários livros publicados.', 'Existem muitos livros sobre a natureza, entre eles os de Ailton Krenak, que são lidos por muitas pessoas no Brasil.'], 0),
     M('Qual repertório é PERTINENTE ao tema “Manipulação do comportamento do usuário pelo controle de dados na internet” (ENEM 2018)?', ['o documentário “O Dilema das Redes”, sobre algoritmos que prendem a atenção', 'o filme “Central do Brasil”, sobre uma mulher que escreve cartas para analfabetos', 'o livro “Vidas Secas”, sobre a seca e a miséria de uma família no sertão', 'o curta “Ilha das Flores”, sobre o desperdício de alimentos e a fome'], 0),
     M('Um aluno escreveu: “Como disse Albert Einstein, ‘as redes sociais vão destruir a humanidade’.” Esse repertório é:', ['ilegítimo, pois Einstein morreu em 1955, muito antes das redes sociais', 'legítimo, pois Einstein foi um cientista famoso e respeitado', 'produtivo, pois a frase está entre aspas e tem um autor', 'de bolso, pois pode ser usado em qualquer tema de redação'], 0),
     M('Qual repertório NÃO é pertinente ao tema “Desafios para a valorização da herança africana no Brasil” (ENEM 2024)?', ['o documentário “O Dilema das Redes”, sobre os algoritmos', 'as leis 10.639/2003 e 11.645/2008, sobre o ensino da cultura afro-brasileira e indígena', 'o poema “O Navio Negreiro”, de Castro Alves', 'a Lei Áurea (1888), que não garantiu direitos aos libertos'], 0),
     VF('Sobre repertório sociocultural, marque V ou F:', [
       ('Repertório de bolso é aquele que pode ser adaptado a vários temas.', True),
       ('Basta citar o nome de um filósofo para o repertório ser produtivo.', False),
       ('Repertório pertinente é aquele que se relaciona com o tema da proposta.', True),
       ('Informações copiadas dos textos motivadores contam como repertório próprio.', False),
       ('Se não souber a frase exata de um autor, é melhor usar paráfrase.', True)]),
     C('Associe cada tema do ENEM ao repertório mais pertinente:', [
       ('Desafios para a formação educacional de surdos no Brasil (2017)', 'Lei Brasileira de Inclusão (Lei 13.146/2015)'),
       ('Democratização do acesso ao cinema no Brasil (2019)', 'artigo 6º da Constituição, que inclui o lazer entre os direitos sociais'),
       ('Invisibilidade e registro civil: garantia de acesso à cidadania no Brasil (2021)', 'Declaração Universal dos Direitos Humanos: direito de ser reconhecido como pessoa perante a lei'),
       ('O estigma associado às doenças mentais na sociedade brasileira (2020)', 'conto “O Alienista”, de Machado de Assis, sobre o tratamento da loucura'),
       ('A persistência da violência contra a mulher na sociedade brasileira (2015)', 'Simone de Beauvoir: “Ninguém nasce mulher: torna-se mulher”')]),
     A('Cite um repertório de bolso e explique por que ele serve para vários temas.', 'Resposta pessoal. Ex.: O artigo 5º da Constituição, segundo o qual todos são iguais perante a lei: serve para temas sobre preconceito, desigualdade e acesso a direitos, pois trata da igualdade de todos.', 2),
     A('Complete o trecho com a etapa que falta, relacionando o repertório ao tema “combate às notícias falsas”: “Para Paulo Freire, a educação deve formar sujeitos críticos, capazes de transformar a realidade. ____”', 'Resposta pessoal. Ex.: Assim, uma escola que ensina a checar fontes e a desconfiar de manchetes sensacionalistas prepara os jovens para não acreditar em notícias falsas nem compartilhá-las.', 2),
     A('Reescreva o trecho tornando o repertório produtivo: “O filme ‘Extraordinário’ é muito bonito. O bullying é um problema.”', 'Resposta pessoal. Ex.: O filme “Extraordinário” mostra como o preconceito fere uma criança com aparência diferente ao entrar na escola; da mesma forma, muitos estudantes brasileiros sofrem bullying, o que prejudica sua autoestima e seu aprendizado.', 3),
     A('Use o curta “Ilha das Flores” (Jorge Furtado, 1989), que mostra pessoas disputando restos de comida com porcos em um lixão, em um trecho de 2 ou 3 linhas sobre o desperdício de alimentos no Brasil. Apresente, explique e relacione.', 'Resposta pessoal. Ex.: O curta “Ilha das Flores”, de Jorge Furtado, mostra pessoas disputando restos de comida com porcos em um lixão. A cena revela a contradição de uma sociedade que desperdiça alimentos enquanto muitos passam fome, realidade ainda presente no Brasil.', 3),
  ],
  producao='Tema: “Caminhos para combater a intolerância religiosa no Brasil” (ENEM 2016). Escreva um parágrafo de desenvolvimento de 7 a 10 linhas com um repertório legítimo e pertinente (sugestões: o artigo 5º da Constituição, que garante a liberdade de crença, ou a Declaração Universal dos Direitos Humanos). Siga os três passos: apresente, explique e relacione o repertório ao tema.')

E(55, 'Argumentação', 'Artigo de opinião',
  aquecimento='Pergunte: “Onde vocês já viram alguém defender uma opinião em público: jornal, site, rádio, vídeo?”. Explique que o artigo de opinião é a versão escrita e assinada desse debate.',
  quadro=['# O que é o artigo de opinião',
    '- Gênero argumentativo publicado em jornais, revistas, sites e blogs, em que um autor defende seu ponto de vista sobre um assunto atual e polêmico.',
    '- Finalidade: convencer o leitor e participar do debate público.',
    '- É assinado: o autor se identifica (nome e, muitas vezes, profissão ou função) e se responsabiliza pela opinião.',
    '- O veículo (jornal, revista, site, blog) e o público definem o grau de formalidade da linguagem.',
    '# Estrutura',
    '- Título: chamativo; muitas vezes já mostra a posição do autor. Ex.: “Cidade sem árvores é cidade doente”.',
    '- Introdução: apresenta o assunto e a tese.',
    '- Desenvolvimento: argumentos (exemplos, dados, autoridade, comparação, contra-argumentação).',
    '- Conclusão: retoma a tese; pode trazer uma sugestão, um alerta ou uma pergunta ao leitor.',
    '- Assinatura: nome e identificação do autor. Ex.: Ana Souza, professora de Geografia.',
    '# Linguagem',
    '- Pode usar a 1ª pessoa (“defendo”, “nós, moradores”), mas a opinião precisa de argumentos.',
    '- Recursos comuns: perguntas retóricas, exemplos do cotidiano, ironia leve e conectivos argumentativos.',
    '- Respeito sempre: o autor critica ideias e fatos, nunca ofende pessoas.',
    '# Artigo de opinião x redação do ENEM',
    '- Artigo: título, assinatura, 1ª pessoa permitida, veículo e público definidos, conclusão livre.',
    '- Redação do ENEM: texto dissertativo-argumentativo, sem assinatura, título opcional, linguagem impessoal e proposta de intervenção obrigatória.',
    '- Nos dois: tese clara, argumentos consistentes, coesão e norma-padrão.',
    '# Gêneros vizinhos',
    '- Notícia: informa um fato, sem defender opinião. Editorial: opinião do próprio jornal, sem assinatura de um autor.',
    '# Fique atento',
    '- Opinião sem argumento não convence: todo “eu penso” precisa de um “porque”.',
    '- Se o texto só informa um fato, ele é notícia, e não artigo de opinião.',
    '- Na redação do ENEM, não use “eu acho”, não assine e não esqueça a proposta de intervenção.',
    '- O título deve combinar com a tese: título que promete uma coisa e texto que defende outra confundem o leitor.'],
  q=[M('Qual é a principal finalidade do artigo de opinião?', ['Defender um ponto de vista e convencer o leitor.', 'Informar um fato de forma imparcial e objetiva.', 'Ensinar a montar um objeto, passo a passo.', 'Contar uma história inventada, com personagens.'], 0),
     M('Qual elemento faz parte do artigo de opinião, mas NÃO deve aparecer na redação do ENEM?', ['a assinatura do autor', 'a tese', 'os argumentos', 'a conclusão'], 0),
     M('No artigo de opinião, o uso da 1ª pessoa (“eu defendo”, “nós, moradores”) é:', ['permitido, desde que a opinião seja bem argumentada', 'proibido em qualquer situação de escrita', 'obrigatório em todos os parágrafos do texto', 'sinal de que o texto é, na verdade, uma notícia'], 0),
     T('Quem passa pela praça do nosso bairro à noite vê bancos quebrados, lâmpadas apagadas e quase ninguém. Defendo que a reforma dessa praça seja prioridade, porque um espaço público abandonado afasta as famílias e deixa a rua mais insegura.\nHá quem diga que existem problemas mais urgentes. Concordo que saúde e educação vêm em primeiro lugar, mas lazer também é direito: o artigo 6º da Constituição o coloca ao lado delas entre os direitos sociais. Além disso, uma praça iluminada e movimentada ajuda a prevenir a violência, já que lugares cheios de gente tendem a ser mais seguros.\nNão se trata de luxo, e sim de devolver aos moradores um lugar de encontro. E você, quando foi a última vez que se sentou naquele banco?\nMarta Oliveira, moradora do bairro e professora',
       fonte='Texto elaborado para esta atividade (autora fictícia).', titulo='Praça é lugar de gente', para=4),
     M('Qual é a tese do artigo?', ['A reforma da praça do bairro deve ser prioridade.', 'Saúde e educação são mais urgentes que o lazer.', 'A praça do bairro sempre esteve cheia de gente.', 'O bairro já tem espaços públicos suficientes.'], 0),
     M('No artigo, o trecho “Há quem diga que existem problemas mais urgentes. Concordo que…, mas lazer também é direito” é um exemplo de:', ['contra-argumentação (concessão e refutação)', 'alusão histórica (fato do passado)', 'dado estatístico (número com fonte)', 'narração (relato de um acontecimento)'], 0),
     M('Que marcas do artigo deveriam ser evitadas em uma redação do ENEM?', ['a 1ª pessoa (“Defendo”) e a assinatura no final', 'a tese clara logo no primeiro parágrafo', 'os conectivos “além disso” e “mas”', 'a citação da Constituição como argumento'], 0),
     A('Qual é a função da pergunta final do artigo (“E você, quando foi a última vez…?”)?', 'É uma pergunta retórica: aproxima o leitor e o faz refletir sobre o abandono da praça, reforçando a tese.', 2),
     M('Qual título já indica a posição do autor, como é comum nos artigos de opinião?', ['“Merenda de qualidade não é favor, é direito”', '“A merenda escolar nas escolas públicas”', '“Informações sobre a merenda escolar”', '“Merenda: o cardápio da semana”'], 0),
     M('O que diferencia o artigo de opinião da notícia?', ['A notícia relata um fato; o artigo de opinião defende um ponto de vista.', 'A notícia sempre traz assinatura; o artigo de opinião nunca traz.', 'O artigo de opinião não pode usar exemplos, dados ou citações.', 'A notícia usa a 1ª pessoa; o artigo de opinião usa só a 3ª.'], 0),
     M('O editorial se diferencia do artigo de opinião porque:', ['expressa a opinião do próprio jornal e não é assinado por um autor', 'é um texto narrativo, com personagens, tempo e espaço definidos', 'nunca defende um ponto de vista sobre os fatos que comenta', 'é sempre escrito em versos, com rimas e estrofes'], 0),
     VF('Compare o artigo de opinião e a redação do ENEM. Marque V ou F:', [
       ('No artigo de opinião, o autor pode escrever “eu defendo”.', True),
       ('Na redação do ENEM, o candidato deve assinar o texto no final.', False),
       ('Os dois textos defendem uma tese com argumentos.', True),
       ('O artigo de opinião precisa terminar com uma proposta de intervenção com agente, ação, modo, finalidade e detalhamento.', False),
       ('Na redação do ENEM, o título é opcional.', True)]),
     C('Associe cada parte do artigo de opinião à sua função:', [
       ('título', 'chama a atenção e pode antecipar a posição do autor'),
       ('introdução', 'apresenta o assunto e a tese'),
       ('desenvolvimento', 'traz os argumentos que sustentam a tese'),
       ('conclusão', 'retoma a tese com uma sugestão, um alerta ou uma pergunta'),
       ('assinatura', 'identifica quem se responsabiliza pela opinião')]),
     A('Reescreva a frase em linguagem impessoal, adequada à redação do ENEM: “Eu acho que a praça precisa ser reformada, porque eu vejo que ela está abandonada.”', 'Ex.: É necessário reformar a praça, uma vez que ela se encontra abandonada.', 2),
     A('Transforme a notícia em uma tese de artigo de opinião: “A prefeitura anunciou que vai cortar as árvores da avenida principal para alargar as pistas.”', 'Resposta pessoal. Ex.: Cortar as árvores da avenida para alargar as pistas é um erro, porque aumenta o calor e incentiva ainda mais o uso do carro.', 2),
     A('Crie um título de artigo de opinião que defenda mais ônibus à noite no seu bairro.', 'Resposta pessoal. Ex.: “Quem trabalha à noite também precisa voltar para casa”.'),
     A('Escreva uma pergunta retórica para encerrar um artigo de opinião contra o desperdício de água.', 'Resposta pessoal. Ex.: Até quando vamos tratar a água como se ela nunca fosse acabar?'),
  ],
  producao='Escreva um artigo de opinião de 10 a 15 linhas para o jornal da escola sobre um destes assuntos: o horário do recreio, a merenda escolar ou o uso da quadra. Inclua título, tese na introdução, dois argumentos (um deles pode ser uma contra-argumentação), conclusão e assinatura com nome e identificação. Você pode usar a 1ª pessoa.')

E(56, 'Argumentação', 'Carta argumentativa e carta aberta',
  aquecimento='Pergunte: “Se vocês pudessem escrever a uma autoridade pedindo uma melhoria para o bairro, para quem escreveriam e o que pediriam?”. Anote no quadro os destinatários e os pedidos.',
  quadro=['# Carta argumentativa',
    '- Carta em que o autor defende um ponto de vista para convencer um interlocutor definido (pessoa ou instituição) a mudar de opinião ou tomar uma atitude.',
    '- Diferentemente da redação do ENEM, há um destinatário explícito, a quem o autor se dirige ao longo do texto.',
    '# Estrutura',
    '- Local e data: no início, geralmente à direita. Ex.: Vila Nova, 10 de março de 2026.',
    '- Vocativo: a quem a carta se dirige, seguido de vírgula ou dois-pontos. Ex.: Senhor Prefeito, / Prezada Senhora Diretora,',
    '- Corpo: apresentação de quem escreve e do assunto, tese, argumentos e pedido (ou proposta).',
    '- Despedida: Atenciosamente, / Respeitosamente, / Cordialmente,',
    '- Assinatura: nome e, se necessário, identificação. Ex.: Ana Lima, aluna do 9º ano.',
    '# Pronomes de tratamento',
    '- Vossa Excelência (V. Ex.ª): altas autoridades, como prefeito, governador, deputado, ministro e juiz.',
    '- Vossa Senhoria (V. S.ª): autoridades em geral e tratamento cerimonioso, como diretores, chefes e gerentes.',
    '- Vossa Magnificência: reitores de universidade. Vossa Santidade: o papa.',
    '- Com pronome de tratamento, verbo e possessivo ficam na 3ª pessoa: “Vossa Excelência conhece sua cidade” (e não “conheceis vossa”).',
    '- Falando com a autoridade: Vossa Excelência. Falando sobre ela: Sua Excelência. Ex.: Sua Excelência, o prefeito, visitou a escola.',
    '# Carta aberta',
    '- Carta publicada (jornal, site, rede social, mural) e dirigida a um destinatário público, mas escrita para ser lida por todos.',
    '- Objetivo: chamar a atenção da sociedade para um problema e pressionar por solução. Pode ser assinada por uma pessoa ou por um grupo.',
    '- Título comum: “Carta aberta ao prefeito de…”, “Carta aberta à comunidade escolar”.',
    '# Carta de reclamação e carta de solicitação',
    '- Reclamação: relata o problema (o quê, quando, onde), mostra o prejuízo e pede solução. Ex.: produto com defeito.',
    '- Solicitação: faz um pedido justificado. Ex.: pedir um semáforo em frente à escola.',
    '# Fique atento',
    '- Não misture tratamentos: quem começou com “Vossa Senhoria” não pode passar para “você”.',
    '- Firmeza não é grosseria: reclamação com ofensas perde a força.',
    '- O interlocutor deve aparecer no texto (vocativo, pronome de tratamento, pedido direto).',
    '- Na carta aberta, explique o problema também para o público, que pode não conhecê-lo.'],
  q=[M('Qual é a ordem correta das partes de uma carta argumentativa?', ['local e data, vocativo, corpo do texto, despedida, assinatura', 'assinatura, vocativo, despedida, corpo do texto, local e data', 'vocativo, assinatura, local e data, corpo do texto, despedida', 'corpo do texto, local e data, assinatura, vocativo, despedida'], 0),
     M('Qual pronome de tratamento se usa ao escrever a um prefeito?', ['Vossa Excelência', 'Vossa Santidade', 'Vossa Magnificência', 'Vossa Alteza'], 0),
     M('Qual despedida é adequada a uma carta formal dirigida a uma autoridade?', ['Respeitosamente,', 'Beijos e abraços,', 'Fui, até mais!', 'Valeu, querido!'], 0),
     T('Vila Nova, 12 de agosto de 2026.\nSenhor Prefeito,\nNós, alunos do 9º ano da Escola Municipal Esperança, dirigimo-nos a Vossa Excelência para solicitar a instalação de uma faixa de pedestres e de um semáforo em frente à nossa escola.\nTodos os dias, centenas de estudantes atravessam a avenida na entrada e na saída das aulas. Como os carros passam em alta velocidade, o risco de atropelamento é grande, e muitos pais precisam sair do trabalho para acompanhar os filhos.\nSabemos que o orçamento municipal tem muitas prioridades. No entanto, a segurança das crianças deve vir em primeiro lugar, já que o Estatuto da Criança e do Adolescente garante prioridade absoluta aos direitos de crianças e adolescentes.\nCertos da atenção de Vossa Excelência, aguardamos uma resposta.\nRespeitosamente,\nAlunos do 9º ano da Escola Municipal Esperança',
       fonte='Texto elaborado para esta atividade (cidade e escola fictícias).', titulo='Carta de solicitação', para=4),
     M('Qual é o objetivo da carta?', ['Solicitar faixa de pedestres e semáforo em frente à escola.', 'Reclamar da qualidade da merenda servida na escola.', 'Agradecer ao prefeito por uma obra já concluída.', 'Convidar o prefeito para a feira de ciências da escola.'], 0),
     M('Na carta, o trecho “Sabemos que o orçamento municipal tem muitas prioridades. No entanto, …” é um exemplo de:', ['concessão seguida de refutação', 'vocativo seguido de despedida', 'alusão a um fato histórico', 'dado estatístico com fonte'], 0),
     A('Copie da carta o vocativo e a despedida.', 'Vocativo: “Senhor Prefeito,”; despedida: “Respeitosamente,”.'),
     M('Na carta, ao mencionar o Estatuto da Criança e do Adolescente, os alunos usam um argumento de:', ['autoridade (lei)', 'exemplificação pessoal', 'comparação', 'alusão histórica'], 0),
     M('Qual frase segue a norma-padrão no uso do pronome de tratamento?', ['Vossa Excelência conhece os problemas de sua cidade.', 'Vossa Excelência conheceis os problemas de vossa cidade.', 'Vossa Excelência conhece os problemas de vossa cidade.', 'Vossa Excelência conheces os problemas de tua cidade.'], 0),
     M('Em “Sua Excelência, o governador, visitou a feira de ciências”, usa-se “Sua”, e não “Vossa”, porque:', ['fala-se sobre a autoridade, e não diretamente com ela', 'o governador é uma autoridade estadual, e não municipal', 'a frase está no pretérito, e não no presente', 'o pronome “Vossa” deixou de existir na língua'], 0),
     M('O que caracteriza uma carta aberta?', ['É publicada e se dirige a um destinatário público, para ser lida por toda a sociedade.', 'É enviada em segredo e só pode ser lida pelo próprio destinatário, nunca por outras pessoas.', 'É escrita sem destinatário definido e sem nenhum pedido, reclamação ou reivindicação.', 'É um bilhete pessoal entre amigos, escrito em linguagem informal e sem argumentos.'], 0),
     VF('Sobre cartas argumentativas, marque V ou F:', [
       ('Na carta argumentativa, o interlocutor é definido e aparece no texto.', True),
       ('O vocativo deve vir depois da assinatura.', False),
       ('Com “Vossa Senhoria”, o verbo fica na 3ª pessoa: “Vossa Senhoria sabe…”.', True),
       ('Em uma carta formal, pode-se começar com “Vossa Senhoria” e depois tratar o destinatário por “você”.', False),
       ('Uma carta aberta pode ser assinada por um grupo, como uma associação de moradores.', True)]),
     C('Associe o pronome de tratamento ao destinatário:', [
       ('Vossa Excelência', 'prefeito, governador, deputado'),
       ('Vossa Senhoria', 'diretor de empresa, gerente, chefe de setor'),
       ('Vossa Magnificência', 'reitor de universidade'),
       ('Vossa Santidade', 'papa')]),
     A('Complete com a forma verbal adequada: “Solicitamos que Vossa Senhoria ____ (analisar) o nosso pedido com atenção.”', 'analise (3ª pessoa do singular do presente do subjuntivo).', banco=['analise', 'analiseis', 'analises']),
     A('Escreva um vocativo adequado para uma carta ao diretor de uma empresa de ônibus.', 'Ex.: Prezado Senhor Diretor,'),
     A('Reescreva a reclamação com linguagem respeitosa, sem perder a firmeza: “Vocês são uns incompetentes e o ônibus nunca passa na hora!”', 'Resposta pessoal. Ex.: Venho informar que os ônibus da linha que atende o meu bairro têm atrasado com frequência, o que prejudica quem depende deles para trabalhar e estudar. Solicito providências.', 3),
     A('Escreva o início de uma carta aberta à comunidade escolar sobre o desperdício na merenda: local e data, vocativo e a primeira frase.', 'Resposta pessoal. Ex.: Vila Nova, 5 de maio de 2026. / Prezada comunidade escolar, / Nós, estudantes do 9º ano, vimos a público alertar para o desperdício de comida no refeitório da nossa escola.', 3),
  ],
  producao='Escreva uma carta de solicitação de 10 a 15 linhas ao prefeito (ou à prefeita) da sua cidade, pedindo uma melhoria para o seu bairro (iluminação, ponto de ônibus coberto, coleta de lixo, praça…). Use local e data, vocativo, apresentação, tese, dois argumentos, pedido, despedida e assinatura, mantendo o tratamento “Vossa Excelência” do início ao fim.')

E(57, 'Argumentação', 'Resumo e paráfrase: dizer com as próprias palavras sem extrapolar nem reduzir',
  aquecimento='Peça a um aluno que conte, em até três frases e sem dar opinião, o último filme ou série a que assistiu. A turma avalia: ele contou o essencial? Inventou algo? Deixou de fora o principal?',
  quadro=['# Resumo',
    '- Texto curto que apresenta as ideias principais de outro texto, com as palavras de quem resume.',
    '- Regras: ser fiel ao original, não copiar frases inteiras, não dar opinião e não acrescentar informações.',
    '- Começa identificando o texto e o autor. Ex.: No artigo “Cidade sem árvores é cidade doente”, a autora defende que…',
    '- Verbos de dizer: o autor afirma, defende, critica, explica, argumenta, sugere, alerta, propõe, conclui.',
    '- Deixa claro que as ideias são do autor: “Segundo o autor…”, “O texto mostra que…”.',
    '# Paráfrase',
    '- Reescrita de um trecho com outras palavras, mantendo exatamente o mesmo sentido.',
    '- Recursos: sinônimos, mudança na ordem da frase, troca da voz ativa pela passiva, troca da classe das palavras.',
    '- Ex.: Original: “A leitura amplia o vocabulário.” Paráfrase: “Quem lê passa a conhecer mais palavras.”',
    '- A paráfrase tem mais ou menos o tamanho do original; o resumo é bem menor.',
    '# Nem extrapolar nem reduzir',
    '- Extrapolar: acrescentar o que o texto não diz (opinião, conclusão própria, exagero, generalização).',
    '- Reduzir (restringir): cortar ideias principais ou tratar um detalhe como se fosse o texto todo.',
    '- Contradizer: afirmar o contrário do que o texto diz.',
    '- Original: “A prática de exercícios melhora a saúde física e mental.”',
    '- Extrapolou: “Só quem faz exercícios é feliz.” Reduziu: “Exercícios fazem bem aos músculos.” Contradisse: “Exercícios não influenciam a mente.”',
    '# Técnica em 4 passos',
    '- 1. Leia o texto inteiro uma vez, sem marcar nada.',
    '- 2. Releia sublinhando a ideia principal de cada parágrafo.',
    '- 3. Liste os tópicos com suas palavras (uma linha por parágrafo).',
    '- 4. Junte os tópicos em texto corrido, com conectivos, e confira com o original.',
    '# Fique atento',
    '- “Achei ótimo” e “concordo com o autor” não cabem no resumo: isso é opinião (fica para a resenha).',
    '- Trocar uma ou outra palavra não é paráfrase: é quase cópia.',
    '- Exemplos e detalhes secundários geralmente ficam fora do resumo.',
    '- Nas questões de leitura, a alternativa que extrapola, reduz ou contradiz o texto está errada.'],
  q=[M('Qual característica é própria de um bom resumo?', ['Apresenta as ideias principais do texto, sem a opinião de quem resume.', 'Copia, palavra por palavra, as frases mais importantes do original.', 'Acrescenta, no final, a opinião de quem resume sobre o texto.', 'Conta apenas os exemplos e os detalhes curiosos do texto.'], 0),
     M('Qual frase é uma paráfrase de “Muitos alunos chegam atrasados porque o ônibus demora”?', ['A demora do ônibus faz muitos estudantes chegarem tarde.', 'Os alunos chegam atrasados porque não querem estudar.', 'Todos os alunos chegam atrasados, todos os dias.', 'O ônibus é pontual, mas os alunos se atrasam.'], 0),
     M('Qual começo é adequado para um resumo?', ['O autor defende que…', 'Eu acho que…', 'Na minha opinião…', 'Parece-me que…'], 0),
     T('As abelhas são muito mais do que produtoras de mel. Ao visitar as flores, elas levam o pólen de uma planta para outra e permitem que muitas delas formem frutos e sementes. Por isso, boa parte dos alimentos que chegam à nossa mesa, como frutas, legumes e café, depende, em alguma medida, desse trabalho silencioso.\nApesar dessa importância, as abelhas enfrentam ameaças sérias. O uso excessivo de agrotóxicos, o desmatamento e as mudanças climáticas têm reduzido suas populações em várias regiões do mundo.\nProteger esses insetos é, portanto, proteger a produção de alimentos. Isso exige o uso mais cuidadoso de agrotóxicos, a preservação de matas e jardins floridos e o incentivo à criação de abelhas nativas sem ferrão, comuns no Brasil.',
       fonte='Texto elaborado para esta atividade.', titulo='Sem abelhas, sem comida', para=4),
     M('Qual alternativa resume corretamente o texto?', ['As abelhas, essenciais à produção de muitos alimentos, estão ameaçadas por agrotóxicos, desmatamento e mudanças climáticas e precisam ser protegidas.', 'As abelhas são importantes sobretudo porque produzem mel; por isso, o texto defende que a criação de abelhas seja ensinada nas escolas.', 'Sem as abelhas, a humanidade desaparecerá em poucos anos; por isso, todos os agrotóxicos devem ser proibidos imediatamente no mundo.', 'As populações de abelhas vêm aumentando no mundo todo, graças ao desmatamento e às mudanças climáticas, que favorecem as flores.'], 0),
     M('A frase “Segundo o texto, as abelhas só servem para produzir mel” deve ser rejeitada porque:', ['contradiz o texto, que diz que elas são “muito mais do que produtoras de mel”', 'resume com fidelidade a ideia central do primeiro parágrafo do texto', 'parafraseia corretamente a conclusão apresentada no último parágrafo', 'acrescenta ao texto um exemplo verdadeiro e bem escolhido pelo leitor'], 0),
     A('Escreva a ideia principal de cada parágrafo do texto, em uma linha para cada um.', '1º: as abelhas polinizam as plantas, e muitos alimentos dependem disso; 2º: elas estão ameaçadas por agrotóxicos, desmatamento e mudanças climáticas; 3º: protegê-las é proteger os alimentos, com menos agrotóxicos, preservação de matas e criação de abelhas nativas.', 3),
     M('A afirmação “Segundo o texto, o café é o alimento que mais depende das abelhas” está errada porque:', ['extrapola: o texto cita o café só como exemplo, sem compará-lo a outros', 'reduz: o texto fala apenas do café, e não de outros alimentos', 'contradiz: o texto afirma que o café não depende das abelhas', 'copia, sem mudar nada, uma frase do segundo parágrafo'], 0),
     M('Original: “A cidade precisa de mais árvores, pois elas diminuem o calor e melhoram o ar.” Qual paráfrase mantém o MESMO sentido?', ['Como as árvores reduzem o calor e deixam o ar mais limpo, a cidade necessita de mais delas.', 'A cidade já tem árvores demais, e elas deixam o ar abafado, pesado e cheio de pólen.', 'As árvores são a única solução para todos os problemas ambientais e sociais da cidade.', 'A cidade precisa de mais árvores apenas para que suas ruas e praças fiquem mais bonitas.'], 0),
     M('Original: “Parte dos jovens brasileiros usa a internet para estudar.” Qual leitura EXTRAPOLA o original?', ['Todos os jovens brasileiros usam a internet apenas para estudar.', 'Alguns jovens brasileiros estudam com a ajuda da internet.', 'Há jovens no Brasil que utilizam a internet nos estudos.', 'Uma parcela dos jovens do país recorre à internet para estudar.'], 0),
     M('Um texto trata das causas e das consequências da poluição dos rios. Um resumo que fala apenas das causas:', ['reduz o texto, pois deixa de fora uma ideia principal', 'extrapola o texto, pois inventa informações novas', 'é completo e fiel, pois as causas são o mais importante', 'contradiz o texto, pois afirma o contrário do original'], 0),
     VF('Sobre resumo e paráfrase, marque V ou F:', [
       ('No resumo, exemplos e detalhes secundários geralmente ficam de fora.', True),
       ('Trocar uma ou duas palavras de um parágrafo inteiro já é uma boa paráfrase.', False),
       ('O resumo deve identificar o texto e o autor resumidos.', True),
       ('Quem resume pode acrescentar uma conclusão própria, desde que seja verdadeira.', False),
       ('A paráfrase mantém o sentido do original com outras palavras.', True)]),
     C('Original: “O consumo excessivo de açúcar pode causar obesidade e diabetes.” Associe cada leitura ao que ela faz com o original:', [
       ('“Comer açúcar em excesso pode levar à obesidade e ao diabetes.”', 'paráfrase fiel'),
       ('“Quem come qualquer doce terá diabetes.”', 'extrapolação'),
       ('“O excesso de açúcar pode engordar.”', 'redução (deixa de fora uma ideia)'),
       ('“O açúcar não tem relação com o diabetes.”', 'contradição')]),
     A('Parafraseie a frase: “O desperdício de água preocupa os especialistas.”', 'Ex.: Os especialistas estão preocupados com o desperdício de água. / Gastar água à toa é motivo de preocupação para os especialistas.'),
     A('Complete com verbos de dizer: “No texto, o autor ____ que o transporte público é caro e ____ a falta de ônibus à noite.”', 'afirma; critica.', banco=['afirma', 'critica', 'adora']),
     A('Resuma em uma ou duas frases: “Muitas pessoas acreditam que estudar à noite, depois do trabalho, é impossível. A EJA mostra o contrário: muitos jovens e adultos concluem os estudos nessas condições. Para isso, contam com horários adaptados, apoio dos professores e, principalmente, força de vontade.”', 'Ex.: O texto afirma que, ao contrário do que muitos pensam, é possível estudar à noite depois do trabalho: na EJA, jovens e adultos concluem os estudos com horários adaptados, apoio dos professores e força de vontade.', 2),
     A('Explique com suas palavras a diferença entre extrapolar e reduzir um texto.', 'Extrapolar é ir além do texto, acrescentando ideias que ele não diz; reduzir é ficar aquém, deixando de fora ideias principais ou tratando um detalhe como se fosse o todo.', 2),
  ],
  producao='Resuma em 5 a 7 linhas o texto “Sem abelhas, sem comida”, desta folha. Use os tópicos que você listou, identifique o texto no início, empregue pelo menos dois verbos de dizer (afirma, explica, alerta, conclui…) e não faça nenhum comentário pessoal.')

E(58, 'Argumentação', 'Resenha crítica',
  aquecimento='Pergunte: “Qual foi o último filme, série, jogo ou livro que vocês indicariam (ou não) a um amigo? Por quê?”. Mostre que dar uma opinião e justificá-la já é começar uma resenha.',
  quadro=['# O que é a resenha crítica',
    '- Texto que apresenta uma obra (livro, filme, série, jogo, álbum, peça) e a avalia com argumentos.',
    '- Resenha crítica = resumo (o que é a obra) + avaliação (o que o resenhista pensa dela e por quê).',
    '- Circula em jornais, revistas, sites, blogs e canais de vídeo; ajuda o leitor a decidir se vai ler, assistir ou jogar.',
    '# Estrutura',
    '- 1. Identificação da obra: título, autor ou diretor, ano, gênero, editora ou plataforma.',
    '- 2. Resumo: apresenta o enredo ou o conteúdo, sem revelar o final (sem spoiler).',
    '- 3. Apreciação crítica: pontos fortes e fracos, com argumentos (enredo, personagens, linguagem, trilha sonora, jogabilidade).',
    '- 4. Recomendação: para quem a obra é indicada (ou não) e por quê.',
    '# Linguagem avaliativa',
    '- Adjetivos e advérbios que avaliam: envolvente, previsível, emocionante, cansativo, brilhantemente, infelizmente.',
    '- Expressões: “o ponto alto é…”, “peca por…”, “vale a pena porque…”, “deixa a desejar em…”.',
    '- Toda avaliação precisa de justificativa: “O livro é envolvente, porque cada capítulo termina com um mistério.”',
    '- A resenha pode usar a 1ª pessoa, mas critica a obra com respeito: crítica não é ofensa.',
    '# Resenha x sinopse x resumo',
    '- Sinopse: apresentação curta do enredo, sem avaliação, para despertar o interesse (ex.: a descrição de um filme no catálogo).',
    '- Resumo: apresenta as ideias principais de um texto, sem opinião.',
    '- Resenha crítica: resume e avalia, com argumentos.',
    '# Exemplo de apreciação (obra em domínio público)',
    '- Em “Memórias Póstumas de Brás Cubas” (1881), Machado de Assis dá voz a um narrador que conta a própria vida depois de morto.',
    '- O ponto alto é esse defunto-autor, que, sem nada a perder, ironiza a futilidade da elite carioca do século XIX.',
    '# Fique atento',
    '- Resenha não é só resumo: sem avaliação, ela vira sinopse.',
    '- Avaliação sem argumento (“é bom porque gostei”) não convence.',
    '- Não conte o final: o leitor da resenha ainda não conhece a obra.',
    '- Separe o resumo (fatos da obra) da apreciação (sua opinião justificada).'],
  q=[M('Qual é a diferença entre resenha crítica e resumo?', ['A resenha crítica também avalia a obra; o resumo apenas apresenta as ideias principais.', 'O resumo sempre avalia a obra; a resenha crítica apenas a apresenta ao leitor.', 'A resenha crítica conta o final da obra; o resumo nunca menciona o final.', 'Os dois são textos narrativos, com personagens, tempo e espaço definidos.'], 0),
     M('Sobre o romance “Dom Casmurro”, de Machado de Assis, qual frase é AVALIATIVA?', ['A narração de Bentinho é tão envolvente que o leitor passa a duvidar do próprio narrador.', 'O romance foi publicado em 1899 e é narrado em primeira pessoa por Bentinho.', 'O narrador da história é Bento Santiago, apelidado de Dom Casmurro.', 'Machado de Assis nasceu no Rio de Janeiro e foi o primeiro presidente da Academia Brasileira de Letras.'], 0),
     M('Uma resenha crítica pode tratar de:', ['livros, filmes, séries, jogos, peças e álbuns musicais', 'apenas livros clássicos da literatura brasileira', 'apenas filmes estrangeiros lançados no cinema', 'apenas notícias publicadas em jornais impressos'], 0),
     T('“O Alienista”, de Machado de Assis, foi publicado em 1882, no livro “Papéis Avulsos”. A narrativa acompanha o médico Simão Bacamarte, que funda em Itaguaí um hospício, a Casa Verde, e passa a internar moradores com base em teorias cada vez mais estranhas sobre a loucura.\nO que mais impressiona na obra é o humor afiado. Com ele, Machado critica a ciência usada de forma autoritária e o poder de quem decide o que é “normal”. A linguagem do século XIX pode parecer difícil no começo, mas os capítulos curtos e as situações absurdas prendem o leitor.\nA leitura é recomendada a quem gosta de histórias que fazem pensar e, especialmente, a estudantes que se preparam para o ENEM, já que o conto dialoga com debates atuais sobre saúde mental. Vale a pena chegar ao final e descobrir a última decisão de Bacamarte.',
       fonte='Texto elaborado para esta atividade.', titulo='Quem é o louco, afinal?', para=4),
     M('Em que parte da resenha aparecem o título, o autor e o ano da obra?', ['na identificação da obra, no início do texto', 'na recomendação, no último parágrafo', 'na apreciação crítica, no segundo parágrafo', 'na assinatura do resenhista, no final'], 0),
     M('Qual trecho da resenha expressa uma AVALIAÇÃO do resenhista?', ['“O que mais impressiona na obra é o humor afiado.”', '“foi publicado em 1882, no livro ‘Papéis Avulsos’”', '“acompanha o médico Simão Bacamarte”', '“funda em Itaguaí um hospício, a Casa Verde”'], 0),
     A('O resenhista aponta uma possível dificuldade da obra. Qual é, e como ele a relativiza?', 'A linguagem do século XIX pode parecer difícil no começo; ele relativiza dizendo que os capítulos curtos e as situações absurdas prendem o leitor.', 2),
     M('Por que a resenha NÃO conta qual é “a última decisão de Bacamarte”?', ['Para não revelar o final e manter o interesse do leitor.', 'Porque o resenhista não leu o conto até o fim.', 'Porque o conto termina sem nenhuma decisão.', 'Porque a resenha não pode ter mais de três parágrafos.'], 0),
     M('Qual texto é uma SINOPSE, e não uma resenha?', ['Um menino descobre que pode conversar com os animais e parte em viagem para salvar a floresta onde mora.', 'Um menino descobre que pode conversar com os animais; a animação é bonita, mas o roteiro é previsível.', 'A animação encanta pelas cores e pela trilha sonora e é indicada para toda a família.', 'Apesar do começo lento, o filme emociona e vale a pena ser visto no cinema com amigos.'], 0),
     M('Qual argumento justifica melhor a avaliação “O jogo é envolvente”?', ['As fases são curtas e cada vitória libera um desafio novo, o que dá vontade de seguir.', 'Eu gostei muito do jogo e pronto; não preciso explicar mais nada para ninguém.', 'Todo mundo da minha sala está jogando, então ele deve ser bom e envolvente.', 'O jogo é envolvente porque consegue envolver de verdade quem está jogando.'], 0),
     M('Qual expressão indica um ponto NEGATIVO da obra?', ['peca por', 'o ponto alto é', 'vale a pena', 'surpreende positivamente'], 0),
     VF('Sobre a resenha crítica, marque V ou F:', [
       ('A resenha crítica combina resumo e avaliação.', True),
       ('Uma boa resenha conta o final da história com detalhes.', False),
       ('Na resenha, a opinião deve ser justificada com argumentos.', True),
       ('Sinopse e resenha crítica são o mesmo gênero, com nomes diferentes.', False),
       ('A resenha pode recomendar a obra a um público específico.', True)]),
     C('Associe cada trecho de uma resenha à parte da estrutura:', [
       ('“‘Triste Fim de Policarpo Quaresma’, romance de Lima Barreto, foi publicado em livro em 1915.”', 'identificação da obra'),
       ('“O major Quaresma, patriota sonhador, tenta valorizar tudo o que é brasileiro.”', 'resumo'),
       ('“A ironia do narrador torna a leitura divertida e, ao mesmo tempo, triste.”', 'apreciação crítica'),
       ('“Leitura indicada a quem quer entender o Brasil dos primeiros anos da República.”', 'recomendação')]),
     A('Transforme a sinopse em resenha, acrescentando uma avaliação justificada: “Dois irmãos encontram um mapa antigo e partem em busca de um tesouro escondido na serra.”', 'Resposta pessoal. Ex.: Dois irmãos encontram um mapa antigo e partem em busca de um tesouro escondido na serra. A aventura é emocionante, porque cada pista leva a um novo desafio, mas o final é previsível.', 3),
     A('Escreva duas expressões avaliativas positivas e duas negativas que podem aparecer em uma resenha.', 'Ex.: positivas: “o ponto alto é”, “emocionante”; negativas: “deixa a desejar”, “previsível”.', 2),
     A('Reescreva a avaliação para que ela fique justificada: “O livro é chato.”', 'Ex.: O livro se torna cansativo, porque as descrições são longas e a história demora a avançar.', 2),
     A('Escreva uma recomendação de uma ou duas frases para uma obra que você conhece, indicando o público e o motivo.', 'Resposta pessoal. Ex.: Recomendo a série a quem gosta de mistério, porque cada episódio traz uma pista nova; não é indicada a crianças pequenas, por ter cenas tensas.', 2),
  ],
  producao='Escreva uma resenha crítica de 10 a 15 linhas sobre um livro, filme, série ou jogo que você conheça bem. Siga a estrutura: identificação da obra, resumo sem revelar o final, apreciação com pelo menos dois argumentos e recomendação. Use pelo menos três expressões avaliativas.')

E(59, 'Argumentação', 'Proposta de redação: tema, textos motivadores e recorte temático (restringir o tema)',
  aquecimento='Escreva no quadro só a palavra “cinema” e peça temas possíveis. Depois, mostre o tema do ENEM 2019, “Democratização do acesso ao cinema no Brasil”, e pergunte: o que mudou? Sobre o que exatamente é preciso escrever?',
  quadro=['# A proposta de redação',
    '- Tem três partes: a instrução (o que fazer), os textos motivadores (para contextualizar) e a frase-tema (o que discutir).',
    '- No ENEM, a instrução pede texto dissertativo-argumentativo, na modalidade escrita formal, sobre o tema, com proposta de intervenção que respeite os direitos humanos.',
    '# Assunto, tema e recorte',
    '- Assunto: a área ampla. Ex.: cinema.',
    '- Tema: o assunto delimitado pela proposta. Ex.: Democratização do acesso ao cinema no Brasil (ENEM 2019).',
    '- Recorte temático: o aspecto específico que o tema exige. Aqui: o acesso da população ao cinema, e não a história do cinema.',
    '# Ler a frase-tema palavra por palavra (sublinhe as palavras-chave)',
    '- “Desafios para…”: discutir os obstáculos (e como superá-los).',
    '- “Caminhos para…”: discutir soluções, sem deixar de explicar o problema.',
    '- “No Brasil” / “na sociedade brasileira”: o foco é a realidade brasileira; outros países só como comparação.',
    '- Palavras como “persistência”, “estigma”, “invisibilidade” e “democratização” fazem parte do recorte e precisam ser discutidas.',
    '# Transformar o tema em pergunta-problema',
    '- “Desafios para a formação educacional de surdos no Brasil” (2017) → O que impede que pessoas surdas tenham boa formação educacional no Brasil?',
    '- “Caminhos para combater a intolerância religiosa no Brasil” (2016) → Como combater a intolerância religiosa no país?',
    '# Textos motivadores',
    '- Trazem dados, leis, opiniões e imagens para contextualizar e inspirar.',
    '- Não podem ser copiados: trechos copiados são desconsiderados, e a cópia integral zera a redação.',
    '- Aproveite as ideias com suas palavras e vá além deles com repertório próprio.',
    '# Delimitar: nem ampliar nem restringir demais',
    '- Ampliar: falar do assunto geral, fora do recorte. Ex.: escrever sobre “a importância do cinema”.',
    '- Restringir demais: tratar só de uma parte pequena. Ex.: falar apenas da meia-entrada para estudantes.',
    '- Delimitar bem: escolher dois aspectos centrais do recorte. Ex.: falta de salas em muitas cidades e preço dos ingressos.',
    '# Fique atento',
    '- Leia a frase-tema pelo menos três vezes e volte a ela a cada parágrafo.',
    '- Escreva a pergunta-problema no rascunho e confira se a tese responde a ela.',
    '- Todas as palavras-chave importam: esquecer uma delas pode levar ao tangenciamento.'],
  q=[M('Na frase-tema “Democratização do acesso ao cinema no Brasil” (ENEM 2019), qual é o assunto amplo?', ['cinema', 'democratização do acesso', 'no Brasil', 'acesso da população'], 0),
     M('Os textos motivadores da proposta de redação servem para:', ['contextualizar o tema e inspirar, sem serem copiados', 'ser copiados na introdução, para ganhar tempo', 'substituir os argumentos e o repertório do candidato', 'mostrar qual nota a redação vai receber'], 0),
     M('No tema “Caminhos para combater a intolerância religiosa no Brasil” (ENEM 2016), a expressão “Caminhos para” pede que o texto discuta:', ['soluções para o problema', 'apenas a história das religiões', 'a opinião de cada religião', 'somente as causas do problema'], 0),
     T('PROPOSTA DE TREINO: A partir da leitura dos textos motivadores e com base nos seus conhecimentos, redija um texto dissertativo-argumentativo sobre o tema “Desafios para a inclusão digital da pessoa idosa no Brasil”, apresentando proposta de intervenção que respeite os direitos humanos.\nTEXTO I: Agendar consultas, receber benefícios e pagar contas são tarefas que migram, cada vez mais, para sites e aplicativos. Para quem não domina essas ferramentas, o que era simples pode se tornar um obstáculo.\nTEXTO II: O Estatuto da Pessoa Idosa (Lei 10.741/2003) garante direitos às pessoas com 60 anos ou mais, entre eles o acesso à educação e à cultura.\nTEXTO III: Na tirinha, um avô tenta fazer uma chamada de vídeo, mas só a orelha dele aparece na tela. O neto ri; depois, senta-se ao lado do avô e ensina, com calma, como segurar o celular.',
       fonte='Proposta e textos elaborados para esta atividade.', titulo='Proposta de redação (treino)', para=4),
     M('Qual é o recorte temático dessa proposta?', ['os obstáculos à inclusão digital das pessoas idosas no Brasil', 'a história da internet e dos computadores no mundo', 'os perigos da internet para crianças e adolescentes', 'a importância da família na vida das pessoas idosas'], 0),
     A('Transforme o tema da proposta em uma pergunta-problema.', 'Ex.: Quais obstáculos impedem que as pessoas idosas sejam incluídas no mundo digital no Brasil, e como superá-los?', 2),
     M('Que ideia a tirinha descrita no Texto III sugere?', ['O ensino paciente da família pode facilitar a inclusão digital do idoso.', 'Os idosos são incapazes de aprender a usar qualquer tecnologia.', 'As chamadas de vídeo são perigosas e devem ser evitadas pelos idosos.', 'Os netos devem resolver sempre as tarefas digitais no lugar dos avós.'], 0),
     M('Um candidato copiou o Texto I inteiro na introdução. Esse trecho:', ['será desconsiderado, pois cópia dos textos motivadores não é produção própria', 'valerá como repertório sociocultural legítimo, pertinente e produtivo', 'garantirá pontos extras na competência 5, a da proposta de intervenção', 'mostrará que ele compreendeu e delimitou muito bem o recorte do tema'], 0),
     M('Na frase-tema “O estigma associado às doenças mentais na sociedade brasileira” (ENEM 2020), qual palavra indica o aspecto específico que o texto deve discutir?', ['estigma', 'sociedade', 'associado', 'brasileira'], 0),
     M('Qual pergunta-problema corresponde ao tema “Invisibilidade e registro civil: garantia de acesso à cidadania no Brasil” (ENEM 2021)?', ['Por que a falta de registro civil deixa pessoas invisíveis e sem acesso à cidadania no Brasil?', 'Como funciona, passo a passo, o atendimento em um cartório de registro civil?', 'Por que algumas pessoas preferem viver sem nenhum documento de identidade?', 'Qual é a história dos documentos de identidade em diferentes países do mundo?'], 0),
     M('Qual delimitação RESTRINGE DEMAIS o tema “Desafios para a valorização de comunidades e povos tradicionais no Brasil” (ENEM 2022)?', ['Falar apenas do artesanato de uma única aldeia, sem discutir desafios de valorização.', 'Discutir o preconceito e a falta de garantia de territórios como desafios a essa valorização.', 'Discutir o desconhecimento da sociedade sobre quilombolas, ribeirinhos e indígenas.', 'Analisar como a invisibilidade desses povos dificulta a sua valorização no país.'], 0),
     VF('Sobre a leitura da proposta de redação, marque V ou F:', [
       ('“No Brasil”, na frase-tema, indica que o foco deve ser a realidade brasileira.', True),
       ('Os textos motivadores podem ser copiados para completar o número de linhas.', False),
       ('Transformar o tema em pergunta-problema ajuda a construir a tese.', True),
       ('Para não errar, o ideal é falar do assunto da forma mais ampla possível.', False),
       ('No tema de 2023, sobre o trabalho de cuidado realizado pela mulher, é preciso discutir a invisibilidade desse trabalho.', True)]),
     C('Associe cada expressão da frase-tema ao que ela exige do texto:', [
       ('“Desafios para…”', 'discutir obstáculos e como superá-los'),
       ('“Caminhos para…”', 'discutir soluções para o problema'),
       ('“no Brasil”', 'focar a realidade brasileira'),
       ('“persistência”', 'explicar por que o problema continua existindo')]),
     A('Sublinhe as palavras-chave e escreva o recorte do tema “Manipulação do comportamento do usuário pelo controle de dados na internet” (ENEM 2018).', 'Palavras-chave: manipulação, comportamento do usuário, controle de dados, internet. Recorte: como a coleta e o controle de dados na internet são usados para manipular o comportamento dos usuários.', 3),
     A('Transforme em pergunta-problema: “A persistência da violência contra a mulher na sociedade brasileira” (ENEM 2015).', 'Ex.: Por que a violência contra a mulher continua existindo na sociedade brasileira, e como enfrentá-la?', 2),
     A('Leia o tema “Desafios para a valorização da herança africana no Brasil” (ENEM 2024). Sobre o que o texto deve tratar? E o que ele não pode fazer?', 'Deve discutir os obstáculos à valorização da herança africana no Brasil (racismo, apagamento da história e da cultura afro-brasileira, intolerância contra religiões de matriz africana) e como superá-los. Não pode falar só da história da África ou da escravidão em geral, sem discutir os desafios de valorização hoje.', 3),
     A('Escreva uma tese para a proposta de treino (inclusão digital da pessoa idosa) que já anuncie dois desafios.', 'Resposta pessoal. Ex.: A falta de cursos adaptados e a digitalização apressada dos serviços são desafios que excluem muitas pessoas idosas do mundo digital no Brasil.', 2),
  ],
  producao='Escolha um tema do ENEM: “O estigma associado às doenças mentais na sociedade brasileira” (2020) ou “Desafios para a valorização de comunidades e povos tradicionais no Brasil” (2022). No rascunho, sublinhe as palavras-chave e escreva o assunto, o tema, o recorte e a pergunta-problema. Depois, escreva uma introdução de 5 a 7 linhas que apresente o tema e uma tese que responda à pergunta.')

E(60, 'Argumentação', 'Fuga ao tema e tangenciamento: nem extrapolar, nem restringir demais',
  aquecimento='Diga um tema (“Desafios do transporte público no seu bairro”) e peça a três alunos uma frase cada. A turma vota se cada frase está “dentro”, “na beirada” ou “fora” do tema.',
  quadro=['# Três situações',
    '- Adequado: o texto discute o tema com o recorte pedido.',
    '- Tangenciamento: o texto aborda só o assunto amplo, sem o recorte (fica “na beirada” do tema).',
    '- Fuga total ao tema: o texto trata de outro assunto, sem relação com a proposta.',
    '# O que acontece no ENEM',
    '- Fuga total ao tema: a redação recebe nota zero.',
    '- Tangenciamento: a redação não é zerada, mas a nota cai muito, principalmente nas competências 2, 3 e 5.',
    '- Também zeram: não atender ao tipo dissertativo-argumentativo, texto com até 7 linhas, cópia integral dos textos motivadores, parte desconectada do tema, folha em branco.',
    '# Exemplo: “Democratização do acesso ao cinema no Brasil” (2019)',
    '- Adequado: A falta de salas em muitas cidades e o alto preço dos ingressos afastam grande parte dos brasileiros do cinema.',
    '- Tangencia: O cinema é uma arte importante, que emociona e diverte. (Fala de cinema, mas não do acesso.)',
    '- Foge: As redes sociais prejudicam a saúde mental dos jovens. (Outro assunto.)',
    '# Nem extrapolar, nem restringir demais',
    '- Ampliar (generalizar): falar do assunto geral, sem o recorte. Ex.: no tema de 2017 (surdos), falar da educação no Brasil sem tratar dos surdos.',
    '- Restringir demais: tratar só de uma parte insuficiente do tema. Ex.: no tema de 2017, falar apenas da falta de intérpretes em uma única escola.',
    '- Extrapolar: ir para outro assunto. Ex.: no tema de 2017, falar da acessibilidade das calçadas para cadeirantes.',
    '# Como não sair do tema',
    '- Retome as palavras-chave do tema (ou sinônimos) na introdução, no início de cada desenvolvimento e na conclusão.',
    '- Teste cada parágrafo: “Ele responde à pergunta-problema?”.',
    '- A proposta de intervenção deve resolver o problema do recorte, e não um problema geral.',
    '# Fique atento',
    '- Tangenciar não zera, mas derruba muito a nota: escreva sobre o tema, e não apenas sobre o assunto.',
    '- Escrever bem sobre outro assunto não salva a redação: fuga total ao tema zera.',
    '- Leia os textos motivadores antes de planejar: eles ajudam a entender o recorte.',
    '- Na dúvida, volte à frase-tema e confira se cada palavra-chave foi discutida, e não apenas citada.'],
  q=[M('Qual situação leva a redação do ENEM à nota ZERO?', ['fuga total ao tema', 'tangenciamento ao tema', 'uso de um repertório pouco conhecido', 'introdução com apenas quatro linhas'], 0),
     M('Tangenciar o tema significa:', ['abordar só o assunto amplo, sem o recorte pedido', 'escrever sobre um assunto sem relação com a proposta', 'discutir exatamente o recorte do tema proposto', 'copiar integralmente os textos motivadores'], 0),
     M('Tema: “O estigma associado às doenças mentais na sociedade brasileira” (ENEM 2020). Qual tese FOGE ao tema?', ['O desmatamento da Amazônia ameaça a biodiversidade brasileira.', 'O preconceito contra quem tem depressão afasta muitos brasileiros do tratamento.', 'A falta de informação faz transtornos mentais serem vistos como fraqueza no Brasil.', 'Ver a ansiedade como “frescura” impede que muitos brasileiros peçam ajuda.'], 0),
     T('Tema: “Invisibilidade e registro civil: garantia de acesso à cidadania no Brasil” (ENEM 2021).\nIntrodução de Júlia: Muitos brasileiros ainda não têm certidão de nascimento e, por isso, são invisíveis para o Estado. Sem esse documento, têm dificuldade para se matricular na escola, receber benefícios sociais e ser atendidos nos serviços públicos. Assim, garantir o registro civil é garantir o acesso à cidadania.\nIntrodução de Rafael: A cidadania é muito importante em uma democracia. Votar, pagar impostos e respeitar as leis são deveres de todo cidadão, e cada um precisa fazer a sua parte para construir um país melhor.\nIntrodução de Bianca: As redes sociais mudaram a forma como os jovens se relacionam. Hoje, muitos passam horas no celular e deixam de conversar com a família, o que prejudica a convivência em casa.',
       fonte='Texto elaborado para esta atividade (estudantes fictícios).', titulo='Três introduções para o mesmo tema', para=4),
     M('A introdução de Júlia:', ['está adequada, pois discute o registro civil como garantia de cidadania', 'tangencia o tema, pois fala apenas de cidadania em geral, sem o recorte', 'foge ao tema, pois trata de um assunto sem nenhuma relação com a proposta', 'restringe demais o tema, pois fala do caso de uma única pessoa'], 0),
     M('A introdução de Rafael:', ['tangencia o tema: fala de cidadania em geral, sem tratar de invisibilidade e registro civil', 'está adequada, pois usa a palavra “cidadania”, que aparece no final da frase-tema', 'foge totalmente ao tema, pois não tem relação nenhuma com a proposta de redação', 'está adequada, pois já apresenta uma proposta de intervenção completa e detalhada'], 0),
     A('Classifique a introdução de Bianca (adequada, tangencia ou foge) e justifique.', 'Foge ao tema: trata de redes sociais e convivência familiar, assunto sem relação com registro civil, invisibilidade e cidadania.', 2),
     A('Reescreva a introdução de Rafael para que ela fique adequada ao tema.', 'Resposta pessoal. Ex.: A cidadania deveria alcançar todos os brasileiros, mas quem não tem registro civil permanece invisível para o Estado. Sem certidão de nascimento, essas pessoas têm dificuldade para estudar, trabalhar com carteira assinada e receber benefícios, o que mostra que o registro é a porta de entrada para a cidadania.', 3),
     M('Tema: “Desafios para a formação educacional de surdos no Brasil” (ENEM 2017). Qual tese está ADEQUADA?', ['A falta de intérpretes de Libras e de escolas bilíngues dificulta a formação educacional dos surdos no Brasil.', 'A educação brasileira enfrenta muitos problemas, como a falta de investimentos e a evasão escolar.', 'As pessoas com deficiência ainda enfrentam muito preconceito no mercado de trabalho brasileiro.', 'A música é uma forma importante de expressão cultural para os povos do mundo inteiro.'], 0),
     M('Tema: “Manipulação do comportamento do usuário pelo controle de dados na internet” (ENEM 2018). A tese “A internet facilitou a comunicação entre as pessoas”:', ['tangencia o tema: fala de internet, sem tratar de dados e manipulação', 'está adequada: discute exatamente o recorte proposto pela frase-tema', 'foge totalmente: trata de um assunto sem nenhuma relação com a internet', 'restringe bem o tema: escolhe um aspecto central e suficiente dele'], 0),
     M('Tema: “A persistência da violência contra a mulher na sociedade brasileira” (ENEM 2015). Um texto que fala apenas de assaltos e roubos nas grandes cidades:', ['tangencia o tema, pois trata da violência em geral, sem o recorte “contra a mulher”', 'está adequado, pois o tema é violência e o texto fala de violência', 'restringe bem o tema, pois escolhe um tipo específico de violência', 'apresenta o recorte completo, pois fala da realidade das cidades brasileiras'], 0),
     M('Tema: “Desafios para o enfrentamento da invisibilidade do trabalho de cuidado realizado pela mulher no Brasil” (ENEM 2023). Um texto que discute apenas o caso de uma avó que cuida do neto aos domingos, sem tratar da invisibilidade desse trabalho:', ['restringe demais o tema, pois trata de um caso isolado e insuficiente', 'amplia o tema para todos os tipos de trabalho que existem', 'extrapola para outro assunto, como o trânsito das cidades', 'apresenta o recorte completo e bem delimitado do tema'], 0),
     VF('Sobre fuga ao tema e tangenciamento, marque V ou F:', [
       ('A fuga total ao tema zera a redação do ENEM.', True),
       ('O tangenciamento também zera a redação, assim como a fuga total.', False),
       ('O tangenciamento prejudica principalmente as competências 2, 3 e 5.', True),
       ('Um texto muito bem escrito sobre outro assunto recebe nota alta, mesmo fugindo ao tema.', False),
       ('A proposta de intervenção deve resolver o problema do recorte, e não um problema geral.', True)]),
     C('Associe cada situação ao seu nome:', [
       ('o texto discute o tema com o recorte pedido', 'adequação ao tema'),
       ('o texto fala só do assunto amplo, sem o recorte', 'tangenciamento'),
       ('o texto trata de um assunto sem relação com a proposta', 'fuga total ao tema'),
       ('o texto trata só de uma parte pequena e insuficiente do tema', 'restrição excessiva')]),
     A('Classifique cada tese como ADEQUADA, TANGENCIA ou FOGE, considerando o tema de 2022, “Desafios para a valorização de comunidades e povos tradicionais no Brasil”: I. O uso excessivo do celular prejudica o sono dos adolescentes. II. O preconceito e a disputa por territórios dificultam a valorização de quilombolas, indígenas e ribeirinhos no Brasil. III. Os povos tradicionais têm culturas muito ricas e diversas.', 'I. foge (outro assunto); II. adequada; III. tangencia (fala dos povos tradicionais, mas não dos desafios para valorizá-los).', 3),
     A('Reescreva a tese para que ela deixe de tangenciar o tema “Desafios para a valorização da herança africana no Brasil” (ENEM 2024): “A África é um continente com muitos países e culturas diferentes.”', 'Resposta pessoal. Ex.: O racismo e o pouco espaço dado à história e à cultura afro-brasileira nas escolas são desafios para a valorização da herança africana no Brasil.', 2),
     A('Explique por que um texto que trata apenas da diferença de salários entre homens e mulheres tangencia o tema de 2023 (invisibilidade do trabalho de cuidado realizado pela mulher).', 'Porque fica no assunto amplo (desigualdade de gênero no trabalho) e não discute o recorte: o trabalho de cuidado com filhos, idosos, doentes e a casa, muitas vezes não remunerado e pouco reconhecido, feito pelas mulheres, e os desafios para enfrentar sua invisibilidade.', 3),
  ],
  producao='Tema: “Caminhos para combater a intolerância religiosa no Brasil” (ENEM 2016). Escreva três teses de uma linha cada: uma ADEQUADA, uma que TANGENCIA e uma que FOGE ao tema, identificando cada uma. Depois, escreva uma introdução de 5 a 7 linhas com a tese adequada, retomando as palavras-chave do tema.')
